add({
  id: 'englang-y11-viewpoint-writing', strand: 'englang-viewpoint', year: 11, term: 2,
  name: 'Paper 2 Q5: Writing to Present a Viewpoint',
  summary: 'Write a convincing article, letter, speech, leaflet or essay that presents a viewpoint for Paper 2 Question 5 (40 marks).',
  specRef: 'AQA 8700 Paper 2 Section B, Q5 (AO5, AO6)',
  styles: [
    { name: 'The task: form, audience, purpose', intro: 'Paper 2 Q5 gives a statement on a topic linked to the reading sources, and asks you to write in a specific form (article, letter, speech, leaflet or essay) presenting your viewpoint. 24 marks for AO5, 16 for AO6. Spend about 45 minutes.', items: [
      M("How many marks is Paper 2 Q5 worth?", ["16", "24", "40", "80"], 2, "<b>40 marks</b> (24 AO5 + 16 AO6)."),
      M("A task says: <i>‘Homework should be banned.’ Write an article for a broadsheet newspaper in which you explain your point of view.</i> What is the form?", ["Speech", "Letter", "Broadsheet newspaper article", "Leaflet"], 2, "Form = <b>article</b> for a broadsheet (serious, formal newspaper)."),
      M("Which features suit a broadsheet article?", ["Headline, strapline, formal register, developed paragraphs", "Dear Sir/Madam and Yours faithfully", "Bullet points only", "Text-speak"], 0, "Articles use headlines and a formal but engaging style."),
      M("Which features suit a letter to a headteacher?", ["Headline and strapline", "Address, ‘Dear Mr/Mrs …’, formal register, ‘Yours sincerely’", "Slang", "Stage directions"], 1, "Letters follow letter conventions."),
      M("Which features suit a speech?", ["Direct address, rhetorical questions, repetition, a strong opening and ending", "Footnotes", "Subheadings and bullet points only", "A bibliography"], 0, "Speeches are written to be heard."),
      TF("You must agree with the statement given in Q5.", false, "False — you can agree, disagree or take a balanced view. Choose the side you can argue most convincingly."),
      M("What does ‘explain your point of view’ suggest about tone?", ["Measured argument with reasons is expected", "Only jokes", "Only facts with no opinion", "Shouting"], 0, "Explain/argue → clear reasons and evidence; persuade → more emotive."),
      MM("Which TWO are part of AO5 for Q5?", ["Matching tone, style and register to purpose and audience", "Using structural and grammatical features to organise ideas", "Shading four boxes", "Analysing a source", "Comparing perspectives"], [0, 1], "AO5 covers content (register, purpose, audience) and organisation."),
      S("Name the formal sign-off for a letter that begins ‘Dear Sir or Madam’. (two words)", "Yours faithfully", ["yours faithfully"], "<b>Yours faithfully</b>."),
      M("Who is the likely audience for a leaflet titled ‘Staying Safe Online: A Guide for Parents’?", ["Toddlers", "Parents", "Teachers only", "Police officers"], 1, "The title names the audience."),
      M("Which is a typical Q5 topic?", ["A statement on an issue linked to the Section A sources, e.g. travel, education, technology", "A story about a dragon", "A poem analysis", "A science experiment"], 0, "Q5 statements are usually linked thematically to the Paper 2 sources."),
      TF("Using the reading sources as a quarry for ideas is allowed in Q5.", true, "True — the theme is linked, so ideas may help, but don't copy text."),
      M("How long should you spend on Q5?", ["About 15 minutes", "About 45 minutes", "About 1 hour 30 minutes", "About 5 minutes"], 1, "About <b>45 minutes</b>."),
      M("Which register suits an article for a teenage magazine?", ["Lively, direct and engaging but still accurate", "Legal and technical", "Text-speak", "Extremely formal and archaic"], 0, "Adapt register to audience — accessible but controlled."),
      M("What is a ‘strapline’ in an article?", ["A short line under the headline expanding on it", "The sign-off", "A footnote", "The final paragraph"], 0, "A strapline/standfirst summarises or hooks beneath the headline."),
    ] },
    { name: 'Building the argument', intro: 'A strong viewpoint has a clear stance, a logical order of points, evidence and examples, a counter-argument with rebuttal, and an ending that leaves an impact. Discourse markers guide the reader through the argument.', items: [
      O("Order a strong viewpoint plan.", ["Engaging introduction setting out your stance", "Strongest supporting point with evidence", "Second point developed with an anecdote", "Counter-argument and rebuttal", "Conclusion with a call to action"], "A logical, building structure with a counter-argument shows control."),
      M("Which discourse marker shows cause and effect?", ["Consequently,", "Meanwhile,", "Once upon a time,", "Suddenly,"], 0, "<b>Consequently</b> signals result."),
      M("Which is the best counter-argument and rebuttal?", ["Some people disagree but they're stupid.", "Admittedly, homework can reinforce learning. However, when it eats into sleep and family time, the cost to wellbeing outweighs any benefit.", "Everyone agrees with me.", "There is no counter-argument."], 1, "Concede fairly, then rebut with reasoning."),
      M("Which evidence is most convincing?", ["‘Everyone knows this.’", "A specific (plausible) statistic or expert view, plus a concrete example", "‘Trust me.’", "‘It's obvious.’"], 1, "Specific evidence persuades."),
      MM("Which TWO make an introduction effective?", ["A striking hook (anecdote, question, statistic)", "‘In this essay I will write about…’", "A clear statement of your viewpoint", "Listing every point you will make", "Starting with ‘Hi’ in a formal article"], [0, 2], "Hook + clear stance."),
      TF("A balanced ‘on the one hand… on the other’ essay with no final judgement is the strongest approach.", false, "False — even a balanced piece should reach a clear conclusion. Examiners reward a convincing viewpoint."),
      M("Which topic sentence is strongest?", ["Another thing is money.", "Above all, a ban on homework would give families back the evenings they have lost.", "Money.", "I will now talk about money."], 1, "Clear, confident, linked to the argument."),
      M("Which sentence uses a tricolon persuasively?", ["Homework is bad.", "Homework steals our sleep, our hobbies and our happiness.", "Homework is homework.", "Homework has words."], 1, "Three items build rhythm and emphasis."),
      M("Which ending is most powerful for a speech against fast fashion?", ["That's the end of my speech.", "So before you click ‘buy’ again, ask yourself one question: who really pays for this T-shirt?", "Thanks.", "Fast fashion exists."], 1, "Direct address, a question and an image leave the audience thinking."),
      S("What do we call returning to an idea from the introduction in the conclusion? (two words, ‘cyclical …’)", "cyclical structure", ["cyclical structure", "cyclical ending", "cyclical"], "A <b>cyclical structure</b> gives satisfying closure."),
      M("Which tone best suits a letter of complaint to a council?", ["Rude and abusive", "Firm, polite and reasoned", "Jokey", "Pleading and desperate throughout"], 1, "Firm courtesy persuades decision-makers."),
      M("Which use of irony would work in a broadsheet article?", ["Yes, let's ban all phones — and while we're at it, the printing press, which also distracted the young.", "LOL phones", "Phones are bad bad bad.", "Ban phones!!!!"], 0, "Controlled irony shows sophistication and wit."),
      TF("Each paragraph should develop one main point, linked to the previous one.", true, "True — cohesion is part of AO5 organisation."),
      M("Which connective best introduces your strongest point last?", ["Most importantly,", "Firstly,", "Meanwhile,", "For example,"], 0, "<b>Most importantly</b> signals climax."),
      M("Which is the best way to use a personal anecdote?", ["As a brief, vivid example that makes the issue human, then link it back to the argument", "As the whole piece", "Instead of a viewpoint", "In the conclusion only, unexplained"], 0, "Anecdotes support the argument rather than replacing it."),
    ] },
    { name: 'Judge and improve viewpoint writing', intro: 'Compare and improve sample sentences and paragraphs so they are more convincing, better matched to audience and form, and technically accurate.', items: [
      M("Which opening for a speech to Year 11s on exam stress is strongest?", ["My speech is about stress.", "Raise your hand if you've ever lain awake at 2 a.m. replaying a maths question. Keep it up if it's happened this week.", "Stress is a thing.", "Hello. Stress."], 1, "Interactive, relatable and vivid."),
      M("Improve: <i>Social media is bad for teenagers because it is bad.</i>", ["Social media is really bad for teenagers.", "Social media trains teenagers to measure their worth in likes, feeding anxiety with every scroll.", "Social media is bad.", "Social media is bad, bad, bad."], 1, "A precise reason and image replace circular reasoning."),
      M("Which version is formal enough for a broadsheet?", ["The government needs to sort this mess out ASAP.", "The government must act urgently to resolve this crisis.", "Govt = useless.", "Sort it out lol."], 1, "Formal, urgent and in Standard English."),
      MM("Which TWO would most improve a mid-band viewpoint piece?", ["Adding a counter-argument and rebuttal", "Repeating the same point in every paragraph", "Varying sentence structures and openings", "Removing paragraphs", "Using more exclamation marks"], [0, 2], "Sophisticated argument and controlled variety."),
      M("Which corrects the error? <i>Their are many reasons why we should act.</i>", ["There are many reasons why we should act.", "They're are many reasons.", "Their is many reasons.", "There is many reasons."], 0, "<b>There are</b> — place/existential ‘there’ with plural verb."),
      M("Which headline is strongest for an article arguing for later school start times?", ["School Times", "Wake Up to the Facts: Why Our Teenagers Need a Later Bell", "Article", "My Opinion"], 1, "Wordplay, clarity and a hint of the argument."),
      TF("Using ‘I think’ at the start of every sentence makes an argument more convincing.", false, "False — it sounds hesitant. State views confidently: ‘Clearly…’, ‘It is time to…’."),
      M("Improve the rhetorical question: <i>Is pollution good?</i>", ["Is pollution bad?", "How much longer will we let our children breathe air we would never choose to drink?", "Pollution?", "Do you like pollution or not?"], 1, "A purposeful, emotive question that implies the answer."),
      M("Which sentence uses a colon accurately for impact?", ["There is only one solution: we must cut traffic in the town centre.", "There is: only one solution.", "There is only one: solution.", "There: is only one solution."], 0, "A colon after a complete clause introduces the solution."),
      M("Which conclusion is weakest?", ["In conclusion, as I have said, I think what I said is right.", "The choice is simple. Act now — or explain to the next generation why we didn't.", "So I urge you: write to your MP today.", "Let us be the generation that finally said enough."], 0, "Circular and vague; the others end with impact."),
      M("Which version varies sentence openings best?", ["I think… I think… I think…", "Undeniably, … / Yet, … / If we act now, …", "The… The… The…", "And… And… And…"], 1, "Varied openings show control (AO6)."),
      S("Correct the spelling: ‘arguement’.", "argument", ["argument"], "<b>argument</b> — drop the e."),
      M("A student writes a letter but includes a headline and subheadings. What's the issue?", ["None", "The conventions don't match the form; use letter conventions", "It should be longer", "It needs more statistics"], 1, "Matching form is part of AO5."),
      O("Order the revision process in the last 5 minutes.", ["Check sentence endings: full stops and no comma splices", "Check apostrophes and homophones", "Check spelling of ambitious vocabulary", "Add or fix one piece of punctuation for effect if time allows"], "Prioritise the errors that cost most marks first."),
      M("Which paragraph shows the most sophisticated control?", ["Phones are bad. They are bad because they are bad. Ban them.", "Some argue that phones keep children safe. Yet safety bought at the cost of attention, sleep and conversation is a poor bargain — and one our schools need not accept.", "Phones phones phones.", "I like phones but also I don't."], 1, "Concession, rebuttal, tricolon and a dash, all accurate and persuasive."),
    ] },
  ],
  learn: {
    overview: "Paper 2 Question 5 asks you to write to present a viewpoint — in the form of an article, letter, speech, leaflet or essay — on a statement linked to the reading sources. It is worth <b>40 marks</b> (24 AO5, 16 AO6), so it deserves a full 45 minutes. Success comes from a clear stance, a well-organised argument and controlled, accurate writing.",
    objectives: ["I can identify form, audience and purpose in a task.", "I can plan a logical argument with a counter-argument.", "I can use rhetorical devices judiciously.", "I can match register and conventions to form."],
    keyWords: [
      { term: "Viewpoint", def: "Your stance on the statement." },
      { term: "Form", def: "Text type: article, letter, speech, leaflet, essay." },
      { term: "Rebuttal", def: "Answering and dismissing a counter-argument." },
      { term: "Discourse marker", def: "A word or phrase that guides the reader through the argument (however, consequently)." },
      { term: "Register", def: "Level of formality." },
      { term: "Call to action", def: "A final instruction urging the reader to act." },
    ],
    sections: [
      { title: 'Decode the task', html: `<p>Example: <i>‘Tourism does more harm than good.’ Write a letter to your local newspaper in which you argue your point of view on this statement.</i></p><table class="qt"><tr><th>Form</th><th>Audience</th><th>Purpose</th></tr><tr><td>Letter to a newspaper</td><td>Local readers, editor</td><td>Argue</td></tr></table>` },
      { title: 'A reliable structure', html: `<ol><li>Hook + stance</li><li>Point 1 (strong) with evidence</li><li>Point 2 with anecdote/emotion</li><li>Counter-argument + rebuttal</li><li>Point 3 (strongest)</li><li>Conclusion: call to action / cyclical return to hook</li></ol>` },
      { title: 'Model paragraph', html: `<div class="worked"><div class="wq">‘Young people today spend too much time indoors.’ Write an article for a broadsheet newspaper giving your view.</div><ol><li>Concede the counter-argument.</li><li>Rebut with reasoning and an image.</li><li>Tricolon and a confident final sentence.</li></ol><div class="wa">Answer: Admittedly, today's teenagers have good reasons to stay in: busy roads, scarce parks and anxious parents. Yet to blame screens alone is to miss the point. We have built towns with nowhere for the young to go, then scolded them for not going there. Give them safe spaces, open fields and a little trust, and they will rediscover the outdoors as surely as we did.</div></div>` },
      { title: 'Form conventions', html: `<table class="qt"><tr><th>Form</th><th>Conventions</th></tr><tr><td>Article</td><td>Headline, strapline, subheadings optional, paragraphs</td></tr><tr><td>Letter</td><td>Dear…, formal paragraphs, Yours sincerely/faithfully</td></tr><tr><td>Speech</td><td>Address the audience, rhetorical devices, ‘thank you for listening’</td></tr><tr><td>Leaflet</td><td>Title, subheadings, clear sections (no need for images)</td></tr><tr><td>Essay</td><td>Introduction, developed paragraphs, conclusion</td></tr></table>` },
    ],
    mistakes: ["Ignoring the form (e.g. no letter conventions).", "A list of devices with no logical argument.", "Repeating the same point in different words.", "Informal register or text-speak in a formal task."],
    examTips: ["Plan for 5–10 minutes: stance, 4–5 points, counter-argument, ending.", "Aim for one deliberate counter-argument and a memorable conclusion.", "Save 5 minutes to proofread for AO6."],
    realLife: "Writing a persuasive letter, application or campaign post can change decisions that affect your life.",
  },
});
